export function BankImportModal({ slug, onImported, onClose: onDismiss }: BankImportModalProps) {
  const [fileName, setFileName] = useState<string | null>(null);
  const [csvBase64, setCsvBase64] = useState<string | null>(null);
  const [account, setAccount] = useState("");
  const [profile, setProfile] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [locked, setLocked] = useState<string | null>(null);
  const [done, setDone] = useState<BankImportSummary | null>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const fileRead = useRef(0);
  const [reading, setReading] = useState(false);

  // Move focus into the dialog and let Escape dismiss it — basic modal hygiene.


  const outcome = useMutationOutcome(onImported);
  const guard = useDiscardGuard(!done && Boolean(csvBase64 || account || profile), onDismiss);
  const { onClose } = guard;

  async function handleFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    const read = ++fileRead.current;
    setError(null);
    setFileName(null);
    setCsvBase64(null);
    setReading(Boolean(file));
    if (!file) return;
    try {
      if (file.size > MAX_BANK_FILE_BYTES) throw new Error("CSV-filen må højst fylde 25 MiB.");
      const bytes = new Uint8Array(await file.arrayBuffer());
      if (read !== fileRead.current) return;
      if (bytes.length > MAX_BANK_FILE_BYTES) throw new Error("CSV-filen må højst fylde 25 MiB.");
      if (!bytes.length) throw new Error("CSV-filen er tom.");
      let binary = "";
      const chunk = 0x8000;
      for (let i = 0; i < bytes.length; i += chunk) {
        binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
      }
      setFileName(file.name);
      setCsvBase64(btoa(binary));
    } catch (err) {
      if (read === fileRead.current) setError(err instanceof Error ? err.message : "Filen kunne ikke læses.");
    } finally {
      if (read === fileRead.current) setReading(false);
    }
  }

  async function handleImport() {
    if (outcome.isBlocked()) return;
    if (reading || !csvBase64) {
      setError("Vælg en CSV-fil først.");
      return;
    }
    setBusy(true);
    setError(null);
    setLocked(null);
    try {
      const summary = await api.importBank(slug, {
        csvBase64,
        account: account.trim() || undefined,
        profile: profile.trim() || undefined,
      }).catch(outcome.reject);
      setDone(summary);
      onImported();
    } catch (err) {
      const e = err as MaybeApiError;
      const message = e?.message ?? "Importen kunne ikke gennemføres.";
      // A 409 conflict from the backup lock is shown kindly, not as an error.
      if (e?.code === "conflict") setLocked(message);
      else setError(message);
    } finally {
      setBusy(false);
    }
  }

  return (
    <Dialog title="Importér kontoudtog" onClose={onClose} busy={busy} initialFocusRef={closeRef}>
    {outcome.feedback}
      {guard.confirmation}



        {done ? (
          // After a successful import the modal becomes a short receipt.
          <>
            <div className="modal-body">
              <p>
                {done.imported}{" "}
                {done.imported === 1 ? "transaktion" : "transaktioner"}{" "}
                importeret
                {done.skippedDuplicates > 0
                  ? ` · ${done.skippedDuplicates} dublet${
                      done.skippedDuplicates === 1 ? "" : "ter"
                    } sprunget over`
                  : ""}
                {done.exceptionsCreated > 0
                  ? ` · ${done.exceptionsCreated} ny${
                      done.exceptionsCreated === 1 ? "" : "e"
                    } opgave${done.exceptionsCreated === 1 ? "" : "r"}`
                  : ""}
                .
              </p>
            </div>
            {done.balanceWarnings.length > 0 && (
              <Banner kind="warning">
                {done.balanceWarnings.join(" ")}
              </Banner>
            )}
            <div className="modal-actions">
              <Button
                type="button"
                className="btn"
                ref={closeRef}
                onClick={onClose}
              >
                Luk
              </Button>
            </div>
          </>
        ) : (
          <>
            <div className="modal-body">
              <p>
                Vælg en bank-CSV. Banktransaktionerne indlæses til afstemning;
                importen bogfører ikke. Kendte dubletter springes over.
              </p>
              <p className={["muted", stylex.props(viewStyles.site0).className].filter(Boolean).join(" ")} >
                Filens originale bytes bevares. Maks. 25 MiB. Standard-CSV bruger
                UTF-8 og understøtter komma, semikolon og tabulator.{" "}
                <a
                  href="https://rentemester.dk/docs/bank-import"
                  target="_blank"
                  rel="noreferrer noopener"
                >
                  Læs mere om CSV-formatet
                </a>
                .
              </p>
              <p className={["muted", stylex.props(viewStyles.site1).className].filter(Boolean).join(" ")} >
                <strong>Understøttede bankprofiler:</strong>{" "}
                {SUPPORTED_BANK_PROFILES.map((p, i) => (
                  <span key={p.name}>
                    {i > 0 ? ", " : ""}
                    <code>{p.name}</code> ({p.label})
                  </span>
                ))}
                . Uden profil skal filen følge standard-CSV-formatet.
              </p>
            </div>

            {locked && <LockBanner message={locked} />}
            {error && <Banner kind="error">{error}</Banner>}

            <label className="modal-field">
              CSV-fil
              <Input
                type="file"
                accept=".csv,text/csv"
                onChange={handleFile}
                disabled={outcome.blocked || (busy)}
              />
            </label>
            {fileName && (
              <p className={["muted", stylex.props(viewStyles.site2).className].filter(Boolean).join(" ")} >
                Valgt: {fileName}
              </p>
            )}

            <label className="modal-field">
              Bankkonto (valgfri)
              <Input
                type="text"
                value={account}
                placeholder="fx hovedkonto eller 1234-5678901234"
                onChange={(e) => setAccount(e.target.value)}
                disabled={outcome.blocked || (busy)}
              />
              <span className="field-hint">
                Kun nødvendigt hvis virksomheden har flere bankkonti og du vil
                styre præcis hvilken konto transaktionerne lægges på. Lad
                feltet stå tomt for at bruge standardkontoen.
              </span>
            </label>

            <label className="modal-field">
              Bankformat (valgfri)
              <Input
                type="text"
                value={profile}
                placeholder="fx danske-bank"
                onChange={(e) => setProfile(e.target.value)}
                disabled={outcome.blocked || (busy)}
              />
              <span className="field-hint">
                Uden profil bruges standard-CSV; tvetydige datoer afvises.
                Angiv danske-bank for Danske Banks semikolon-CSV med
                dag-måned-år i UTF-8 eller Windows-1252.
              </span>
            </label>

            <div className="modal-actions">
              <Button variant="secondary"
                type="button"
                className="btn secondary"
                onClick={onClose}
                disabled={busy}
              >
                Annullér
              </Button>
              <Button requiredPermission="company.ledger.post"
                type="button"
                className="btn"
                onClick={handleImport}
                disabled={outcome.blocked || (busy || reading || !csvBase64)}
              >
                {busy ? "Importerer…" : "Importér"}
              </Button>
            </div>
          </>
        )}

    </Dialog>
  );
}

export type BankImportModalProps = {
  /** Company slug the import targets. */
  slug: string;
  /** Re-runs the Bank view load after a successful import. */
  onImported: () => void;
  /** Closes the modal without acting. */
  onClose: () => void;
};

async function handleFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    const read = ++fileRead.current;
    setError(null);
    setFileName(null);
    setCsvBase64(null);
    setReading(Boolean(file));
    if (!file) return;
    try {
      if (file.size > MAX_BANK_FILE_BYTES) throw new Error("CSV-filen må højst fylde 25 MiB.");
      const bytes = new Uint8Array(await file.arrayBuffer());
      if (read !== fileRead.current) return;
      if (bytes.length > MAX_BANK_FILE_BYTES) throw new Error("CSV-filen må højst fylde 25 MiB.");
      if (!bytes.length) throw new Error("CSV-filen er tom.");
      let binary = "";
      const chunk = 0x8000;
      for (let i = 0; i < bytes.length; i += chunk) {
        binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
      }
      setFileName(file.name);
      setCsvBase64(btoa(binary));
    } catch (err) {
      if (read === fileRead.current) setError(err instanceof Error ? err.message : "Filen kunne ikke læses.");
    } finally {
      if (read === fileRead.current) setReading(false);
    }
  }

async function handleImport() {
    if (outcome.isBlocked()) return;
    if (reading || !csvBase64) {
      setError("Vælg en CSV-fil først.");
      return;
    }
    setBusy(true);
    setError(null);
    setLocked(null);
    try {
      const summary = await api.importBank(slug, {
        csvBase64,
        account: account.trim() || undefined,
        profile: profile.trim() || undefined,
      }).catch(outcome.reject);
      setDone(summary);
      onImported();
    } catch (err) {
      const e = err as MaybeApiError;
      const message = e?.message ?? "Importen kunne ikke gennemføres.";
      // A 409 conflict from the backup lock is shown kindly, not as an error.
      if (e?.code === "conflict") setLocked(message);
      else setError(message);
    } finally {
      setBusy(false);
    }
  }

