      {!detail&&<ImportedReceivablesPanel slug={slug} />}
      {publicNotice&&<Banner kind="warning">{publicNotice}</Banner>}
      {inv.nativeSales&&!inv.archived&&can("company.external-send")&&<div className="card">
        <h2>E-faktura</h2>
