            {inv.nativeSales && <label>Beløb inkl. moms (valgfrit)<Input inputMode="decimal" value={creditGross} onChange={e => setCreditGross(e.target.value)} placeholder="Tomt felt krediterer hele restbeløbet" /></label>}
            </>
