 const [query,setQuery]=useState("");const [cursor,setCursor]=useState(0);
 const list=useAsync(signal=>request<{rows:Party[];count:number;nextCursor:number|null}>(`${path}?query=${encodeURIComponent(query)}&cursor=${cursor}&limit=25`,{signal}),[slug,query,cursor,refreshVersion]);
 const [selected,setSelected]=useState<string>();const detail=useAsync(signal=>selected?request<{party:Party}>(`${path}/${encodeURIComponent(selected)}`,{signal}):Promise.resolve(undefined),[slug,selected]);
 const reload=()=>{list.reload();detail.reload();};const outcome=useMutationOutcome(reload,"workspace-parties");
