 async function submit(e:FormEvent){e.preventDefault();if(!confirmed||busy||outcome.isBlocked())return;setBusy(true);setResult(undefined);setSuccess(false);try{let body:Record<string,unknown>;let endpoint=path;if(action==="create"){body={kind,name,aliases:JSON.parse(aliases),identifiers:JSON.parse(identifiers),source,observedAt:observed,reviewAssertion:review,role,defaults:JSON.parse(defaults)};}else{if(!selected)throw new Error("Vælg en synlig part først.");endpoint+=`/${encodeURIComponent(selected)}/${action}`;body=action==="role"?{role,defaults:JSON.parse(defaults)}:action==="alias"?{alias:value,source,observedAt:observed,reviewState}:{field,value,source,observedAt:observed,reviewState};}const response=await request<{party:Party}>(endpoint,{method:"POST",body:JSON.stringify({...body,confirm:true})}).catch(outcome.reject);setSelected(response.party.partyId);setConfirmed(false);setSuccess(true);setResult("Registreret. Se kilder, assertions og historik i serverens aktuelle læsning.");reload();}catch(error){setResult(error instanceof Error?error.message:"Partændringen kunne ikke bekræftes.");}finally{setBusy(false);}}
 return <section className="card" aria-label="Workspace-parter"><h3>Canonical parter</h3><p className="muted">Identiteter er fælles i workspacet. Kun dine aktuelt synlige virksomhedsrelationer vises. Kildebaserede felt- og aliasassertions ændrer aldrig den oprindelige identitet eller bogføring automatisk. Globale assertions kræver masterdata-adgang til alle tilknyttede virksomheder; arkiverede relationer kan blokere.</p>
