 {list.data&&<><p>{list.data.count} synlige parter</p>{list.data.count===0&&<p className="muted">Ingen synlige parter endnu.</p>}<ul>{list.data.rows.map(p=><li key={p.partyId}><Button variant="secondary" onClick={()=>{setSelected(p.partyId);setConfirmed(false);}}>{p.name}</Button><code>{p.partyId}</code><span>{p.kind} · {p.roles.map(r=>`${r.companySlug}: ${r.role}`).join(", ")}</span></li>)}</ul>{cursor>0&&<Button variant="secondary" onClick={()=>setCursor(0)}>Første side</Button>}{list.data.nextCursor!==null&&<Button variant="secondary" onClick={()=>setCursor(list.data!.nextCursor!)}>Næste side</Button>}</>}
 {detail.error&&<ErrorState message={detail.error} onRetry={detail.reload}/>}{detail.data&&<details open><summary>Partens oprindelse og historik: {detail.data.party.partyId}</summary><pre>{JSON.stringify(detail.data.party,null,2)}</pre><p>Brug dette partyId som knowledge-kildereference; serveren kontrollerer din aktuelle synlighed igen.</p></details>}
