 {(action==="assertion"||action==="alias")&&<>{action==="assertion"&&<label>Felt <Input aria-label="Party field" required value={field} onChange={e=>setField(e.target.value)}/></label>}<label>Assertionværdi <Input aria-label="Party value" required value={value} onChange={e=>setValue(e.target.value)}/></label><label>Reviewstatus <Select aria-label="Party review state" value={reviewState} onChange={e=>setReviewState(e.target.value)}>{["proposed","approved","rejected"].map(s=><option key={s}>{s}</option>)}</Select></label></>}
