 const [rows,setRows]=useState<YearFiles[]>([{id:1,year:"",postings:null,balances:null},{id:2,year:"",postings:null,balances:null}]);const next=useRef(3);
 const [currency,setCurrency]=useState("");const [review,setReview]=useState<Review|null>(null);const [confirmed,setConfirmed]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [done,setDone]=useState<ArchiveImportReceipt|null>(null);
 const archives=useAsync(signal=>archiveImportApi.list(slug,{signal}),[slug]);
 const [selectedYear,setSelectedYear]=useState<number|null>(null);
 const detail=useAsync(signal=>selectedYear===null?Promise.resolve(null):archiveImportApi.year(slug,selectedYear,{signal}),[slug,selectedYear]);
 const storageKey=`rentemester:archive-import-attempt:${scope}`;
 const [pending,setPending]=useState<Pending|null>(()=>{try{const p=JSON.parse(sessionStorage.getItem(storageKey)??"null");return p&&typeof p.idempotencyKey==="string"&&hash(p.planHash)&&hash(p.sourceSha256)?p:null;}catch{return null;}});
 const marker=useMutationBlock(`${scope}:archive-import`);const alive=useRef(true),working=useRef(false);const caps=useCapabilities(slug);
 const [reconciled,setReconciled]=useState(false);const [reconciliation,setReconciliation]=useState("");
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;};},[]);
 const guard=useDiscardGuard(Boolean(review||pending||rows.some(r=>r.postings||r.balances)),()=>setReview(null));
