                          {formatPercent(y.egenkapitalandel)}
                        </td>
                        {showDelta ? (
                          <DeltaPp
                            current={y.egenkapitalandel}
                            prior={prior?.egenkapitalandel ?? null}
                            partial={isPartial}
                          />
                        ) : null}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </section>
  );
