export function AccountsView() {
  const { slug = "" } = useParams();
  const state = useAsync<CompanyAccounts>((signal) => api.accounts(slug, { signal }), [slug]);
  const [typeFilter, setTypeFilter] = useState<string>("");
  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    const needle = search.trim().toLowerCase();
    return (state.data?.accounts ?? []).filter((a) => {
      if (typeFilter !== "" && a.type !== typeFilter) return false;
      if (needle === "") return true;
      return (
        a.accountNo.toLowerCase().includes(needle) ||
        a.name.toLowerCase().includes(needle) ||
        (a.defaultVatCode ?? "").toLowerCase().includes(needle)
      );
    });
  }, [state.data, typeFilter, search]);

  if (state.loading) return <Loading />;
  if (state.error) return <ErrorState message={state.error} />;
  const data = state.data!;

  return (
    <section className="accounts-view">
      <PageHeader title="Kontoplan" actions={<><div className="row-actions">
          <ButtonLink className="btn secondary" to={`/companies/${slug}/manage`}>
            Administrér
          </ButtonLink>
        </div></>}>
        <div>

          <p className="muted">
            {data.company.cvr ? `CVR ${data.company.cvr} · ` : ""}
            {data.company.country} · {data.company.currency} · Kontoplan
          </p>
        </div>

      </PageHeader>

      <p className="muted">
        {data.accounts.length} konti i kontoplanen. Kontoplanen kommer som
        standard fra Rentemester og opdateres automatisk når du migrerer fra
        et andet system. En konto, der allerede har bogføringslinjer, kan ikke
        ændres — det er en garanti for at de tidligere posteringer bliver
        stående uændret.
      </p>

      <section className="card">
        <h3>Sammentælling pr. type</h3>
        <div className="filter-bar">
          {Object.entries(data.byType)
            .sort((a, b) => a[0].localeCompare(b[0]))
            .map(([type, count]) => (
              <Button
                key={type}
                type="button"
                className={`btn small ${typeFilter === type ? "primary" : "secondary"}`}
