function ReopenPeriodModal({
  slug,
  target,
  onClose: onDismiss,
  onRefresh,
  onDone,
  onError,
}: {
  slug: string;
  target: AccountingPeriodRow;
  onClose: () => void;
  onRefresh: () => void;
  onDone: () => void;
  onError: (msg: string) => void;
}) {
