export function fullTransfer(t: Transfer): boolean {
  return /^[a-f0-9]{64}$/.test(t.stateHash ?? "") && Array.isArray(t.offeredArchiveHashes) && Array.isArray(t.pendingEffects) && Array.isArray(t.history);
}

