 const partyNames=new Map(sources.data?.parties.rows.map(p=>[p.partyId,p.name])??[]),recordNames=new Map(sources.data?.records.rows.map(r=>[r.recordId,r.filename])??[]);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;serial.current++;read.current?.abort();};},[]);
