                  <option value="">— vælg faktura —</option>
                  {openInvoices.map((inv) => (
                    <option key={inv.documentId} value={String(inv.documentId)}>
                      {inv.invoiceNo}
                      {inv.customerName ? ` · ${inv.customerName}` : ""} ·{" "}
                      {formatKroner(inv.openBalance, inv.currency)} åben
                    </option>
                  ))}
