                onClick={handleBook}
                disabled={
                  outcome.blocked || (busy ||
                  noneMatchable ||
                  openInvoices === null ||
                  typeof selectedId !== "number")
                }
              >
                {busy ? "Bogfører…" : "Bogfør"}
              </Button>
            </div>
          </>
        )

